const fs = require('node:fs');
const path = require('node:path');

function main() {
  const args = process.argv.slice(2);
  if (args.length < 2) {
    console.error('Usage: node rebuild-shared-chat-html.js <input.html> <output.html>');
    process.exit(1);
  }

  const [inputPathArg, outputPathArg] = args;
  const inputHtmlPath = path.resolve(inputPathArg);
  const outputHtmlPath = path.resolve(outputPathArg);

  if (!fs.existsSync(inputHtmlPath)) {
    throw new Error(`Input HTML file not found: ${inputHtmlPath}`);
  }

  const html = fs.readFileSync(inputHtmlPath, 'utf8');
  const marker = '.streamController.enqueue(';

  let cursor = 0;
  let mainPayload = null;
  let payloadCallStart = -1;
  let payloadArgStart = -1;
  let payloadArgEnd = -1;

  while (true) {
    const start = html.indexOf(marker, cursor);
    if (start === -1) break;
    const argStart = start + marker.length;

    let argEnd = html.indexOf(');\n</script>', argStart);
    if (argEnd === -1) {
      argEnd = html.indexOf(');</script>', argStart);
    }
    if (argEnd === -1) {
      cursor = argStart + 1;
      continue;
    }

    const rawArg = html.slice(argStart, argEnd).trim();
    let decodedStr = null;

    try {
      decodedStr = JSON.parse(rawArg);
    } catch (_) {
      // Fall back to scanning if not pure JSON-string literal
    }

    if (typeof decodedStr === 'string' && decodedStr.trim().startsWith('[')) {
      try {
        const parsedArray = JSON.parse(decodedStr.trim());
        if (Array.isArray(parsedArray)) {
          mainPayload = parsedArray;
          payloadCallStart = start;
          payloadArgStart = argStart;
          payloadArgEnd = argEnd;
          break;
        }
      } catch (_) {}
    }

    cursor = argStart + 1;
  }

  if (!mainPayload) {
    throw new Error('Could not locate valid flattened turbo-stream payload in HTML');
  }

  const targetKeys = new Set([
    'is_visually_hidden_from_conversation',
    'is_redacted',
    'hide_inline_actions'
  ]);

  const keyIndices = new Map();
  for (let i = 0; i < mainPayload.length; i++) {
    const item = mainPayload[i];
    if (typeof item === 'string' && targetKeys.has(item)) {
      keyIndices.set(i, item);
    }
  }

  if (keyIndices.size === 0) {
    throw new Error('Target metadata keys were not found in payload string pool');
  }

  let falseSlotIndex = mainPayload.findIndex(item => item === false);
  function getFalseSlot() {
    if (falseSlotIndex === -1) {
      falseSlotIndex = mainPayload.length;
      mainPayload.push(false);
    }
    return falseSlotIndex;
  }

  const counts = {
    is_visually_hidden_from_conversation: 0,
    is_redacted: 0,
    hide_inline_actions: 0
  };

  for (let i = 0; i < mainPayload.length; i++) {
    const item = mainPayload[i];
    if (!item || typeof item !== 'object' || Array.isArray(item)) continue;

    for (const [k, vSlot] of Object.entries(item)) {
      let propName = null;
      if (k.startsWith('_')) {
        const keyIdx = parseInt(k.slice(1), 10);
        if (keyIndices.has(keyIdx)) {
          propName = keyIndices.get(keyIdx);
        }
      } else if (targetKeys.has(k)) {
        propName = k;
      }

      if (!propName) continue;

      let isSemanticTrue = false;
      if (vSlot === true) {
        isSemanticTrue = true;
      } else if (typeof vSlot === 'number' && vSlot >= 0 && vSlot < mainPayload.length) {
        if (mainPayload[vSlot] === true) {
          isSemanticTrue = true;
        }
      }

      if (isSemanticTrue) {
        if (typeof vSlot === 'boolean') {
          item[k] = false;
        } else {
          item[k] = getFalseSlot();
        }
        counts[propName]++;
      }
    }
  }

  const totalChanged = counts.is_visually_hidden_from_conversation + counts.is_redacted + counts.hide_inline_actions;
  if (totalChanged === 0) {
    throw new Error('No target boolean true properties were found to mutate');
  }

  const serializedPayload = JSON.stringify(mainPayload);
  const serializedArg = JSON.stringify(serializedPayload);
  const rebuiltHtml = html.slice(0, payloadArgStart) + serializedArg + html.slice(payloadArgEnd);

  fs.mkdirSync(path.dirname(outputHtmlPath), { recursive: true });
  fs.writeFileSync(outputHtmlPath, rebuiltHtml, 'utf8');

  const summary = {
    status: 'SUCCESS',
    input_path: inputHtmlPath,
    output_path: outputHtmlPath,
    total_changed: totalChanged,
    changed_counts: counts
  };
  console.log(JSON.stringify(summary, null, 2));
}

if (require.main === module) {
  main();
}

module.exports = { main };
